INSERT INTO "INDEXER_SITES" ("ID", "NAME", "DOMAIN", "SEARCH", "PARSER", "PUBLIC", "TORRENTS", "CATEGORY", "EXTRA") VALUES ('dmhy', '动漫花园', 'https://dmhy.org/', '{"paths":[{"path":"topics/list?keyword={keyword}","method":"get"}]}', '', 1, '{"list":{"selector":"table.tablesorter > tbody > tr"},"fields":{"id":{"selector":"a[href*=\"/topics/list/sort_id/\"]","attribute":"href","filters":[{"name":"re_search","args":["\\d+",0]}]},"title":{"selector":"td.title > a"},"details":{"selector":"td.title > a","attribute":"href"},"download":{"selector":"a.download-arrow.arrow-magnet","attribute":"href"},"date_added":{"selector":"td:nth-child(1) > span","optional":true},"date":{"text":"{% if fields[''date_elapsed''] or fields[''date_added''] %}{{ fields[''date_elapsed''] if fields[''date_elapsed''] else fields[''date_added''] }}{% else %}now{% endif %}","filters":[{"name":"dateparse","args":"%Y-%m-%d %H:%M:%S"}]},"size":{"selector":"td:nth-child(5)"},"seeders":{"selector":"td:nth-child(6)"},"leechers":{"selector":"td:nth-child(7)"},"grabs":{"selector":"td:nth-child(8)"},"downloadvolumefactor":{"case":{"*":0}},"uploadvolumefactor":{"case":{"*":1}}}}', '{"list":{"selector":"div.central-container > table > tbody > tr.js-search-results-row"},"fields":{"id":{"selector":"tr.js-search-results-row","attribute":"data-itemindex"},"title":{"selector":"td:nth-child(1) > a.magnet-link-wrap"},"details":{"selector":"td:nth-child(1) > a.magnet-link-wrap","attribute":"href"},"download":{"selector":"td:nth-child(1) > a.js-magnet.magnet-link","attribute":"data-clipboard-text"},"date_added":{"selector":"td:nth-child(3)"},"size":{"selector":"td:nth-child(2)"},"downloadvolumefactor":{"case":{"*":0}},"uploadvolumefactor":{"case":{"*":1}}}}', '{"render": false, "proxy": true, "en_expand": false, "source_type": "ANIME", "search_param": "kw"}') ON CONFLICT(ID) DO UPDATE SET NAME = excluded.NAME, DOMAIN = excluded.DOMAIN, SEARCH = excluded.SEARCH, PARSER = excluded.PARSER, TORRENTS = excluded.TORRENTS, CATEGORY = excluded.CATEGORY;
INSERT INTO "INDEXER_SITES" ("ID", "NAME", "DOMAIN", "SEARCH", "PARSER", "PUBLIC", "TORRENTS", "CATEGORY", "EXTRA") VALUES ('mikanani', 'MiKan', 'https://mikanani.me/', '{"paths":[{"path":"Home/Search?searchstr={keyword}","method":"get"}]}', '', 1, '{"list":{"selector":"div.central-container > div.episode-table > table > tbody > tr.js-search-results-row"},"fields":{"id":{"selector":":scope","attribute":"data-itemindex"},"title":{"selector":"td:nth-child(2) > a.magnet-link-wrap"},"details":{"selector":"td:nth-child(2) > a.magnet-link-wrap","attribute":"href"},"download":{"selector":"td:nth-child(2) > a.js-magnet.magnet-link","attribute":"data-clipboard-text"},"date_added":{"selector":"td:nth-child(4)"},"size":{"selector":"td:nth-child(3)"},"downloadvolumefactor":{"case":{"*":0}},"uploadvolumefactor":{"case":{"*":1}}}}', '', '{"render": false, "proxy": true, "en_expand": false, "source_type": "ANIME", "search_param": "kw"}') ON CONFLICT(ID) DO UPDATE SET NAME = excluded.NAME, DOMAIN = excluded.DOMAIN, SEARCH = excluded.SEARCH, PARSER = excluded.PARSER, TORRENTS = excluded.TORRENTS, CATEGORY = excluded.CATEGORY;